from collections import Counter
if 1 == 1:
	if 1 == 1:
		n = 100
		smallest = [1 for i in range(n + 1)]
		for i in range(2, n + 1):
			if smallest[i] == 1:
				smallest[i] = 0
				for j in range(2, n // i + 1):
					if smallest[i * j] == 1:
						smallest[i * j] = i
		prime = []
		position = {}
		for k in range(2, len(smallest)):
			if smallest[k] == 0:
				position[k] = len(prime)
				prime += [k]
		for x in prime:
			smallest[x] = x

		def listfactor(R):
			T = []
			while R > 1:
				temp = smallest[R]
				T += [temp]
				R = R // temp
			return Counter(T)
result = [[] for i in range(len(prime))]
small = set([2, 3, 5, 7])
for i in range(len(result)):
	if prime[i] not in small:
		a = prime[i] ** 3
		temp = [0] * a
		for j in range(a):
			temp[j ** 3 % a] = 1
		result[i] += [temp]
	elif prime[i] == 2:
		for j in range(1, 7):
			a = (prime[i] ** j) ** 3
			temp = [0] * a
			for k in range(a):
				temp[pow(k, 3, a)] = 1
			result[i] += [temp]
	elif prime[i] == 3:
		for j in range(1, 5):
			a = prime[i] ** (3 * j)
			temp = [0] * a
			for k in range(a):
				temp[pow(k, 3, a)] = 1
			result[i] += [temp]
	else:
		for j in range(1, 3):
			a = prime[i] ** (3 * j)
			temp = [0] * a
			for k in range(a):
				temp[pow(k, 3, a)] = 1
			result[i] += [temp]
T = int(input())
for _ in range(T):
	(K, C) = list(map(int, input().strip().split(' ')))
	P = listfactor(K)
	a = K ** 3 - C
	check = 0
	for p in P:
		r = P[p]
		r = r - 1
		t = position[p]
		TTT = result[t][r]
		need = a % p ** (3 * r + 3)
		if TTT[need] == 0:
			check = 1
			break
	if check == 0:
		print('YES')
	else:
		print('NO')
